package oracle;
import java.util.*;import java.io.*;import java.lang.reflect.*;import org.json.simple.*;import org.json.simple.parser.JSONParser;
import core.game.node.scenery.*;import core.game.node.item.GroundItem;import core.game.system.task.Pulse;import core.game.world.map.*;import core.game.world.update.flag.chunk.ObjectUpdateFlag;import core.net.packet.*;
public class Support{
 static JSONObject input;static TreeMap<String,Scenery> nodes;static TreeMap<String,Pulse> tasks;static List<Pulse> queue;static Map<String,GroundItem[]> items;static List<Object> events;static Map<String,Integer> calls;static List<Map> hooks;static LinkedHashMap<String,RegionChunk> chunks;static LinkedHashMap<String,List<ObjectUpdateFlag>> flags;static int gen,pt;static boolean enabled;public static core.net.IoSession session;
 static int n(Object v){return((Number)v).intValue();}static int v(Map m,String k,int d){return m.get(k)==null?d:n(m.get(k));}static boolean b(Map m,String k){return Boolean.TRUE.equals(m.get(k));}static Location location(Object v){List a=(List)v;return new Location(n(a.get(0)),n(a.get(1)),n(a.get(2)));}
 public static List<Integer> coords(Location l){return Arrays.asList(l.getX(),l.getY(),l.getZ());}
 static Scenery node(Object name){return name==null?null:nodes.get(name);}static String label(Scenery o){if(o==null)return null;for(Map.Entry<String,Scenery> e:nodes.entrySet())if(e.getValue()==o)return e.getKey();String name="g"+gen++;nodes.put(name,o);return name;}
 static Pulse pulse(Object name){return name==null?null:tasks.get(name);}
 static String pulseLabel(Pulse p){if(p==null)return null;for(Map.Entry<String,Pulse> e:tasks.entrySet())if(e.getValue()==p)return e.getKey();String name="t"+pt++;tasks.put(name,p);return name;}
 public static class Failure extends RuntimeException{public void printStackTrace(){events.add(Arrays.asList("exception"));}}
 public static void emit(String event,Object...args){if(!enabled)return;List<Object> row=new ArrayList<>();row.add(event);Collections.addAll(row,args);events.add(row);int call=calls.merge(event,1,Integer::sum);for(Map h:hooks)if(event.equals(h.get("event"))&&call==v(h,"at",1))for(Object a:(List)h.get("actions"))act((Map)a);}
 public static Scenery remove(Scenery o){emit("remove",label(o));Scenery current=input.containsKey("removeResult")?node(input.get("removeResult")):o;if(current==null)return null;current.setActive(false);o.setActive(false);return current;}
 public static void add(Scenery o){emit("add",label(o));o.setActive(true);o.setRenderable(true);}
 public static RegionChunk chunk(Location l){String key=l.getChunkBase().getX()+","+l.getChunkBase().getY()+","+l.getZ();emit("chunk",coords(l));return chunks.computeIfAbsent(key,k->new RegionChunk(l.getChunkBase()));}
 static Scenery flagObject(ObjectUpdateFlag f){try{Field v=ObjectUpdateFlag.class.getDeclaredField("object");v.setAccessible(true);return(Scenery)v.get(f);}catch(Exception e){throw new RuntimeException(e);}}
 static boolean flagRemove(ObjectUpdateFlag f){try{Field v=ObjectUpdateFlag.class.getDeclaredField("remove");v.setAccessible(true);return(boolean)v.get(f);}catch(Exception e){throw new RuntimeException(e);}}
 public static void flag(RegionChunk c,ObjectUpdateFlag f){String key=c.base.getX()+","+c.base.getY()+","+c.base.getZ();emit("flag",key,label(flagObject(f)),flagRemove(f));flags.computeIfAbsent(key,k->new ArrayList<>()).add(f);}
 public static void submit(Pulse p){String name=pulseLabel(p);emit("submit",name);queue.add(p);}
 public static void ground(GroundItem i){emit("ground",i==null?null:i.id);}
 static class Custom extends Pulse{String name;boolean finish;Custom(String n,Map m){super(v(m,"delay",1));name=n;finish=!Boolean.FALSE.equals(m.get("finish"));running=!Boolean.TRUE.equals(m.get("stopped"));}public boolean pulse(){emit("custom",name);return finish;}public void stop(){emit("stop",name);super.stop();}}
 static Object act(Map a){String op=(String)a.get("op");Scenery o=node(a.get("node")),other=node(a.get("other"));switch(op){
 case "swap":return SceneryBuilder.replace(o,other,!Boolean.FALSE.equals(a.get("clip")),b(a,"permanent"));
 case "temporary":return SceneryBuilder.replace(o,other,v(a,"ticks",1),!Boolean.FALSE.equals(a.get("clip")));
 case "add":return label(SceneryBuilder.add(o,v(a,"ticks",-1),a.containsKey("items")?items.get(a.get("items")):new GroundItem[0]));
 case "remove":return a.containsKey("ticks")?SceneryBuilder.remove(o,n(a.get("ticks"))):SceneryBuilder.remove(o);
 case "update":{List a2=(List)a.get("nodes");Scenery[] ns=new Scenery[a2.size()];for(int i=0;i<ns.length;i++)ns[i]=node(a2.get(i));SceneryBuilder.update(ns);return null;}
 case "active":o.setActive(b(a,"value"));return null;case "renderable":o.setRenderable(b(a,"value"));return null;case "rotate":o.setRotation(n(a.get("value")));return null;case "location":o.setLocation(location(a.get("value")));return null;
 case "wrapper":o.setWrapper(other);return null;case "replaced":((Constructed)o).setReplaced(other);return null;case "restore":o.setRestorePulse(tasks.get(a.get("pulse")));return null;case "destruction":o.setDestructionPulse(tasks.get(a.get("pulse")));return null;
 case "setItem":items.get(a.get("items"))[n(a.get("index"))]=a.get("value")==null?null:new GroundItem(n(a.get("value")));return null;
 case "tick":{int count=queue.size();for(int i=0;i<count;i++){Pulse p=queue.remove(0);if(!p.update()&&p.isRunning())queue.add(p);}return null;}
 case "pulse":return tasks.get(a.get("pulse")).pulse();case "fail":throw new Failure();
 case "flush":{List<Object> out=new ArrayList<>();for(String key:flags.keySet()){RegionChunk c=chunks.get(key);IoBuffer buffer=core.net.packet.out.UpdateAreaPosition.getChunkUpdateBuffer(new core.game.node.entity.player.Player(),c.base);for(ObjectUpdateFlag f:flags.get(key))f.write(buffer);session.write(buffer);List<Integer> bytes=new ArrayList<>();for(byte x:session.bytes)bytes.add(x&255);out.add(bytes);}return out;}
 default:throw new IllegalArgumentException(op);
 }}
 static Map<String,Object> map(Object...pairs){Map<String,Object> m=new TreeMap<>();for(int i=0;i<pairs.length;i+=2)m.put((String)pairs[i],pairs[i+1]);return m;}
 static Object snap(){Map<String,Object> ns=new TreeMap<>();for(String key:new ArrayList<>(nodes.keySet())){Scenery o=nodes.get(key);ns.put(key,o==null?null:map("id",o.getId(),"shape",o.getType(),"rotation",o.getRotation(),"location",coords(o.getLocation()),"active",o.isActive(),"renderable",o.isRenderable(),"constructed",o instanceof Constructed,"wrapper",o.getWrapper()==o?null:label(o.getWrapper()),"replaced",o instanceof Constructed?label(((Constructed)o).getReplaced()):null,"restore",pulseLabel(o.getRestorePulse()),"destruction",pulseLabel(o.getDestructionPulse())));}
  Map<String,Object> ps=new TreeMap<>();for(String key:new ArrayList<>(tasks.keySet())){Pulse p=tasks.get(key);try{Field f=Pulse.class.getDeclaredField("ticksPassed");f.setAccessible(true);Field d=Pulse.class.getDeclaredField("delay");d.setAccessible(true);Field ch=Pulse.class.getDeclaredField("checks");ch.setAccessible(true);Object[] checks=(Object[])ch.get(p);List<Object> cs=null;if(checks!=null){cs=new ArrayList<>();for(Object o:checks)cs.add(label((Scenery)o));}ps.put(key,map("running",p.isRunning(),"ticks",f.get(p),"delay",d.get(p),"checks",cs));}catch(Exception e){throw new RuntimeException(e);}}
  List<String> q=new ArrayList<>();for(Pulse p:queue)q.add(pulseLabel(p));Map<String,Object> fs=new TreeMap<>();for(String key:flags.keySet()){List<Object> v=new ArrayList<>();for(ObjectUpdateFlag f:flags.get(key))v.add(Arrays.asList(label(flagObject(f)),flagRemove(f)));fs.put(key,v);}Map<String,Object> its=new TreeMap<>();for(String key:items.keySet()){GroundItem[] a=items.get(key);List<Object> v=null;if(a!=null){v=new ArrayList<>();for(GroundItem i:a)v.add(i==null?null:i.id);}its.put(key,v);}return map("nodes",ns,"pulses",ps,"queue",q,"flags",fs,"items",its,"events",new ArrayList<>(events));
 }
 static String error(Throwable e){if(e instanceof NullPointerException)return"Null";if(e instanceof ClassCastException)return"Type";if(e instanceof Failure)return"Binding";if(e instanceof IllegalStateException)return"State";if(e instanceof IllegalArgumentException)return"Direction";return e.getClass().getSimpleName();}
 static void setup(JSONObject c){input=c;enabled=false;nodes=new TreeMap<>();tasks=new TreeMap<>();queue=new ArrayList<>();items=new TreeMap<>();events=new ArrayList<>();calls=new HashMap<>();hooks=(List<Map>)c.getOrDefault("hooks",new ArrayList<>());chunks=new LinkedHashMap<>();flags=new LinkedHashMap<>();gen=pt=0;session=new core.net.IoSession();core.cache.def.impl.SceneryDefinition.defs.clear();Map<String,Map> rows=new TreeMap<>((Map)c.get("nodes"));for(Map.Entry<String,Map> e:rows.entrySet()){Map r=e.getValue();if(r==null){nodes.put(e.getKey(),null);continue;}Scenery o=b(r,"constructed")?new Constructed(n(r.get("id")),location(r.get("location")),v(r,"shape",0),v(r,"rotation",0)):new Scenery(n(r.get("id")),location(r.get("location")),v(r,"shape",0),v(r,"rotation",0));nodes.put(e.getKey(),o);}
  Map<String,Map> pulses=new TreeMap<>((Map)c.getOrDefault("pulses",new JSONObject()));for(String name:pulses.keySet())tasks.put(name,new Custom(name,pulses.get(name)));
  for(String key:rows.keySet()){Map r=rows.get(key);Scenery o=nodes.get(key);if(o==null)continue;o.setWrapper(node(r.get("wrapper")));if(o instanceof Constructed)((Constructed)o).setReplaced(node(r.get("replaced")));o.setRestorePulse(pulse(r.get("restore")));o.setDestructionPulse(pulse(r.get("destruction")));}
  Map<String,Object> arrays=(Map)c.getOrDefault("items",new JSONObject());for(String key:arrays.keySet()){List a=(List)arrays.get(key);GroundItem[] ar=null;if(a!=null){ar=new GroundItem[a.size()];for(int i=0;i<ar.length;i++)ar[i]=a.get(i)==null?null:new GroundItem(n(a.get(i)));}items.put(key,ar);}enabled=true;
 }
 public static void main(String[] args)throws Exception{try(BufferedReader r=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){JSONObject c=(JSONObject)new JSONParser().parse(line);setup(c);List<Object> out=new ArrayList<>();for(Object a:(List)c.get("actions")){events.clear();Object result=null;String failure=null;try{result=act((Map)a);}catch(Throwable e){failure=error(e);}Map<String,Object> s=(Map<String,Object>)snap();s.put("result",result);s.put("error",failure);out.add(s);}c.put("expected",out);System.out.println(JSONValue.toJSONString(c));}}}
}
